output_text:
[
  {
    "id": "must_collect_entry_cart",
    "text": "A shopper must take the available shopping cart from the entrance cart station before completing the trip.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_station": "at(1,5)",
        "cart_available_at_entrance": {
          "and": [
            "entrance_cart_station",
            "cartAt(1,5)"
          ]
        },
        "pushing_cart": "hasCart"
      },
      "events": {
        "collect_entry_cart": {
          "pre": {
            "and": [
              "entrance_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "pushing_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "collect_entry_cart"
    }
  },
  {
    "id": "items_only_with_cart",
    "text": "Items should only be picked up while the shopper is pushing a cart.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "not_pushing_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "pickup_item": {
          "pre": "PICKUP_ITEM",
          "post": null
        },
        "pickup_item_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "not_pushing_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "pickup_item_without_cart"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "Shoppers are prohibited from carrying merchandise by hand rather than placing it in a cart.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull",
        "hands_free": {
          "not": "handFull"
        }
      },
      "events": {
        "become_hand_full": {
          "pre": {
            "not": "handFull"
          },
          "post": "handFull"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_by_hand"
    }
  },
  {
    "id": "return_cart_to_front_bay",
    "text": "After taking a cart, the shopper must return it to the front cart-return bay before the trip ends.",
    "abstraction": {
      "state_properties": {
        "front_cart_return_bay": "at(0,1)",
        "pushing_cart": "hasCart",
        "cart_parked_front": "cartAt(0,1)"
      },
      "events": {
        "take_cart": {
          "pre": "PICKUP_CART",
          "post": "pushing_cart"
        },
        "return_cart_front": {
          "pre": {
            "and": [
              "front_cart_return_bay",
              "pushing_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_front"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_cart",
      "discharge": "return_cart_front"
    }
  },
  {
    "id": "cart_drop_only_front",
    "text": "A cart may only be put down at the designated front cart-return bay.",
    "abstraction": {
      "state_properties": {
        "front_cart_return_bay": "at(0,1)",
        "outside_front_cart_return_bay": {
          "not": "front_cart_return_bay"
        }
      },
      "events": {
        "leave_cart_outside_front_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "outside_front_cart_return_bay"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_outside_front_bay"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "Shoppers are forbidden to leave the store while still pushing a shopping cart.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "exit_cell": "at(9,5)"
      },
      "events": {
        "exit_while_pushing_cart": {
          "pre": {
            "and": [
              "EXIT",
              "pushing_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_while_pushing_cart"
    }
  },
  {
    "id": "exit_only_after_cart_parked",
    "text": "The shopper may exit only after the cart is parked at the front return location.",
    "abstraction": {
      "state_properties": {
        "cart_parked_front": "cartAt(0,1)",
        "cart_not_parked_front": {
          "not": "cartAt(0,1)"
        }
      },
      "events": {
        "exit_before_cart_parked": {
          "pre": {
            "and": [
              "EXIT",
              "cart_not_parked_front"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_before_cart_parked"
    }
  },
  {
    "id": "no_interactions_after_cart_return",
    "text": "Once the cart has been returned to the front bay, no further shopping interactions are allowed before exiting.",
    "abstraction": {
      "state_properties": {
        "front_cart_returned": {
          "and": [
            "cartAt(0,1)",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {
        "post_return_interaction": {
          "pre": {
            "and": [
              "front_cart_returned",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "post_return_interaction"
    }
  }
]
